/// The category's own label for a value it does not know, when it has one.
pub(crate) fn fallback(locale: Locale, category: WireCategory) -> Option<&'static str> {
    Some(match category {
        WireCategory::TransferReason => s::wire_transfer_reason_fallback(locale),
        WireCategory::DeskTicketStatus => s::wire_desk_ticket_status_fallback(locale),
        WireCategory::KnowledgeDocumentStatus => s::wire_knowledge_document_status_fallback(locale),
        WireCategory::NumberStatus => s::wire_number_status_fallback(locale),
        _ => return None,
    })
}

